const btn = document.getElementById("btn");
const msg = document.getElementById("msg");
let count = 0;

btn?.addEventListener("click", () => {
  count += 1;
  msg.textContent = `Bạn đã bấm ${count} lần`;
});

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  display: grid;
  place-items: center;
  font-family: system-ui, sans-serif;
  background: #ecfdf5;
  color: #134e4a;
}

.card {
  width: min(420px, 90vw);
  padding: 28px;
  border-radius: 16px;
  background: #fff;
  box-shadow: 0 12px 40px rgb(15 118 110 / 12%);
  text-align: center;
}

h1 {
  margin: 16px 0 8px;
  color: #0f766e;
}

button {
  margin-top: 8px;
  border: 0;
  border-radius: 8px;
  padding: 10px 16px;
  background: #0f766e;
  color: #fff;
  font-weight: 600;
  cursor: pointer;
}

button:hover {
  background: #115e59;
}

#msg {
  min-height: 1.5em;
  color: #0f766e;
  font-weight: 600;
}
